plugins {
    java
}

val processConfigurationData by tasks.registering(Copy::class) {
    description = "Copies and processes configuration files for the runtime environment."
    from(layout.projectDirectory.dir("src/configs"))
    include("*.json")
    into(layout.buildDirectory.dir("processedConfigs"))

    // Explicitly declaring inputs and outputs for incremental build support
    inputs.property("environment", "production")
}

tasks.named("compileJava") {
    dependsOn(processConfigurationData)
}
